36	type registeredOperation struct {
37		ToolName    string
38		OperationID string
39		Method      string
40		Path        string
41		Operation   *openAPIOperation
42		InputSchema jsonSchema
43	}
44	
45	var wordBoundary = regexp.MustCompile(`([a-z0-9])([A-Z])`)
46	
47	func buildCuratedTools(registry map[string]*openAPIOperation) ([]*sdkmcp.Tool, map[string]*registeredOperation, error) {
48		tools := make([]*sdkmcp.Tool, 0, len(curatedOperationIDs))
49		operations := map[string]*registeredOperation{}
50		for _, operationID := range curatedOperationIDs {
51			operation, ok := registry[operationID]
52			if !ok {
53				return nil, nil, errors.Errorf("curated OpenAPI operation %q not found", operationID)
54			}
55	
56			tool, registered := buildToolFromOperation(operation)
57			if _, exists := operations[tool.Name]; exists {
58				return nil, nil, errors.Errorf("duplicate MCP tool name %q", tool.Name)
59			}
60	
61			tools = append(tools, tool)
62			operations[tool.Name] = registered
63		}
64		return tools, operations, nil
65	}
